cypress_script:
describe('Customer Registration Form', () => {
  it('should register a new user with valid information', () => {
    cy.visit('https://parabank.parasoft.com/parabank/register.htm');
    cy.get('#customer.firstName').type('John');
    cy.get('#customer.lastName').type('Doe');
    cy.get('#customer.address.street').type('123 Main St');
    cy.get('#customer.address.city').type('Anytown');
    cy.get('#customer.address.state').type('CA');
    cy.get('#customer.address.zipCode').type('90210');
    cy.get('#customer.phoneNumber').type('5551234567');
    cy.get('#customer.ssn').type('123-45-6789');
    cy.get('#customer.username').type('johndoe');
    cy.get('#customer.password').type('Password123');
    cy.get('#repeatedPassword').type('Password123');
    cy.get('input[type="submit"][value="Register"]').click();
    cy.url().should('include', '/successPagePath'); // replace with actual success URL
  });

  it('should show an error when required fields are left empty', () => {
    cy.visit('https://parabank.parasoft.com/parabank/register.htm');
    cy.get('input[type="submit"][value="Register"]').click();
    cy.url().should('include', '/register.htm');
    // Assert that error messages are displayed based on validation
  });
});

