     await page.fill('#customer.firstName', 'John');
     await page.fill('#customer.lastName', 'Doe');
     await page.fill('#customer.address.street', '123 Main St');
     await page.fill('#customer.address.city', 'Anytown');
     await page.fill('#customer.address.state', 'CA');
     await page.fill('#customer.address.zipCode', '90210');
     await page.fill('#customer.phoneNumber', '5551234567');
     await page.fill('#customer.ssn', '123-45-6789');
     await page.fill('#customer.username', 'johndoe');
     await page.fill('#customer.password', 'Password123');
     await page.fill('#repeatedPassword', 'Password123');
     await page.click('input[type="submit"][value="Register"]');
     await page.waitForNavigation();
     expect(page.url()).toContain('/successPagePath'); // replace with actual success URL
   });

   test('should show an error when required fields are left empty', async ({ page }) => {
     await page.goto('https://parabank.parasoft.com/parabank/register.htm');
     await page.click('input[type="submit"][value="Register"]');
     expect(page.url()).toContain('/register.htm');
     // Assert that error messages are displayed based on validation
   });
 });
